// Cache for getComments.
const get_comments_cache = {};
/**
 * Get all comments belonging to an issue.
 *
 * @param octokit - Initialized Octokit REST client.
 * @param owner   - Repository owner.
 * @param repo    - Repository name.
 * @param number  - Issue number.
 * @return Promise resolving to an array of all comments on that given issue.
 */
async function getComments(octokit, owner, repo, number) {
    const issueComments = [];
    const cacheKey = `${owner}/${repo} #${number}`;
    if (get_comments_cache[cacheKey]) {
        utils_debug(`get-comments: Returning list of all comments on ${cacheKey} from cache.`);
        return get_comments_cache[cacheKey];
    }
    utils_debug(`get-comments: Get list of all comments on ${cacheKey}.`);
    for await (const response of octokit.paginate.iterator(octokit.rest.issues.listComments, {
        owner,
        repo,
        issue_number: number,
        per_page: 100,
    })) {
        for (const comment of response.data) {
            issueComments.push(comment);
        }
    }
    get_comments_cache[cacheKey] = issueComments;
    return issueComments;
}
