/**
 * Get Information about a project board.
 *
 * @param octokit          - Initialized Octokit REST client.
 * @param projectBoardLink - The link to the project board.
 * @return Project board information.
 */
async function getProjectDetails(octokit, projectBoardLink) {
    const projectRegex = /^(?:https:\/\/)?github\.com\/(?<ownerType>orgs|users)\/(?<ownerName>[^/]+)\/projects\/(?<projectNumber>\d+)/;
    const matches = projectBoardLink.match(projectRegex);
    if (!matches) {
        utils_debug(`triage-issues > update-board: Invalid project board link provided. Cannot triage to a board`);
        return {};
    }
    const { groups: { ownerType, ownerName, projectNumber }, } = matches;
    const projectInfo = {
        ownerType: ownerType === 'orgs' ? 'organization' : 'user', // GitHub API requests require 'organization' or 'user'.
        ownerName,
        projectNumber: parseInt(projectNumber, 10),
    };
    utils_debug(`triage-issues > update-board: Fetching info about project board.`);
    // First, use the GraphQL API to request the project's node ID,
    // as well as info about the first 20 fields for that project.
    const projectDetails = await octokit.graphql(`query getProject($ownerName: String!, $projectNumber: Int!) {
			${projectInfo.ownerType}(login: $ownerName) {
				projectV2(number: $projectNumber) {
					id
					fields(first:20) {
						nodes {
							... on ProjectV2Field {
								id
								name
							}
							... on ProjectV2SingleSelectField {
								id
								name
								options {
									id
									name
								}
							}
						}
					}
				}
			}
		}`, {
        ownerName: projectInfo.ownerName,
        projectNumber: projectInfo.projectNumber,
    });
    const details = projectDetails;
    // Extract the project node ID.
    const projectNodeId = details[projectInfo.ownerType]?.projectV2.id;
    if (projectNodeId) {
        projectInfo.projectNodeId = projectNodeId; // Project board node ID. String.
    }
    // Extract the ID of the Priority field.
    const priorityField = details[projectInfo.ownerType]?.projectV2.fields.nodes.find(field => field.name === 'Priority');
    if (priorityField) {
        projectInfo.priority = priorityField; // Info about our Priority column (id as well as possible values).
    }
    // Extract the ID of the Status field.
    const statusField = details[projectInfo.ownerType]?.projectV2.fields.nodes.find(field => field.name === 'Status');
    if (statusField) {
        projectInfo.status = statusField; // Info about our Status column (id as well as possible values).
    }
    // Extract the ID of the Team field.
    const teamField = details[projectInfo.ownerType]?.projectV2.fields.nodes.find(field => field.name === 'Team');
    if (teamField) {
        projectInfo.team = teamField; // Info about our Team column (id as well as possible values).
    }
    // Extract the ID of the Type field.
    const typeField = details[projectInfo.ownerType]?.projectV2.fields.nodes.find(field => field.name === 'Type');
    if (typeField) {
        projectInfo.type = typeField; // Info about our Type column (id as well as possible values).
    }
    return projectInfo;
}
/**
 * Check if an issue is on our project board.
 * If it is, return the ID of the project item.
 *
 * @param octokit     - Initialized Octokit REST client.
 * @param projectInfo - Info about our project board.
 * @param repoName    - The name of the repository.
 * @param issueId     - The ID of the issue.
 * @return The ID of the project item, or an empty string if not found.
 */
async function getIssueProjectItemId(octokit, projectInfo, repoName, issueId) {
    const { ownerName, projectNumber } = projectInfo;
    // First, use the GraphQL API to request the project item IDs for each of the boards this issue belongs to.
    const projectItemDetails = await octokit.graphql(`query getProjectItems($ownerName: String!, $repoName: String!, $issueId: Int!) {
			repository( owner: $ownerName, name: $repoName ) {
				issue( number: $issueId ) {
					projectItems( first: 20 ) {
						... on ProjectV2ItemConnection {
							nodes {
								... on ProjectV2Item {
									id,
									project {
										number
									}
								}
							}
						}
					}
				}
			}
		}`, {
        ownerName,
        repoName,
        issueId,
    });
    const details = projectItemDetails;
    // Only keep the project item ID for the project board we're interested in.
    const projectItemId = details.repository.issue.projectItems.nodes.find(item => item.project.number === projectNumber)?.id;
    return projectItemId || '';
}
/**
 * Add Issue to our project board.
 *
 * @param payload     - Issue event payload.
 * @param octokit     - Initialized Octokit REST client.
 * @param projectInfo - Info about our project board.
 * @return Info about the project item id that was created.
 */
async function addIssueToBoard(payload, octokit, projectInfo) {
    const { issue: { number, node_id }, repository: { owner: { login: ownerLogin }, name, }, } = payload;
    const { projectNodeId } = projectInfo;
    // Add our PR to that project board.
    const projectItemDetails = await octokit.graphql(`mutation addIssueToProject($input: AddProjectV2ItemByIdInput!) {
			addProjectV2ItemById(input: $input) {
				item {
					id
				}
			}
		}`, {
        input: {
            projectId: projectNodeId,
            contentId: node_id,
        },
    });
    const details = projectItemDetails;
    const projectItemId = details.addProjectV2ItemById.item.id;
    if (!projectItemId) {
        utils_debug(`triage-issues > update-board: Failed to add issue to project board.`);
        return '';
    }
    utils_debug(`triage-issues > update-board: Added issue to project board.`);
    // Add label to indicate that the issue was automatically triaged.
    await octokit.rest.issues.addLabels({
        owner: ownerLogin,
        repo: name,
        issue_number: number,
        labels: ['[Status] Auto-allocated'],
    });
    return projectItemId;
}
/**
 * Set custom priority field for a project item.
 *
 * @param octokit       - Initialized Octokit REST client.
 * @param projectInfo   - Info about our project board.
 * @param projectItemId - The ID of the project item.
 * @param priorityText  - Priority of our issue (must match an existing column in the project board).
 * @return The new project item id.
 */
async function setPriorityField(octokit, projectInfo, projectItemId, priorityText) {
    const { projectNodeId, // Project board node ID.
    priority: { id: priorityFieldId, // ID of the priority field.
    options, }, } = projectInfo;
    // Find the ID of the priority option that matches our PR priority.
    const priorityOptionId = options.find(option => option.name === priorityText)?.id;
    if (!priorityOptionId) {
        utils_debug(`triage-issues > update-board: Priority ${priorityText} does not exist as a column option in the project board.`);
        return '';
    }
    const projectNewItemDetails = await octokit.graphql(`mutation ( $input: UpdateProjectV2ItemFieldValueInput! ) {
			set_priority: updateProjectV2ItemFieldValue( input: $input ) {
				projectV2Item {
					id
				}
			}
		}`, {
        input: {
            projectId: projectNodeId,
            itemId: projectItemId,
            fieldId: priorityFieldId,
            value: {
                singleSelectOptionId: priorityOptionId,
            },
        },
    });
    const details = projectNewItemDetails;
    const newProjectItemId = details.set_priority.projectV2Item.id;
    if (!newProjectItemId) {
        utils_debug(`triage-issues > update-board: Failed to set the "${priorityText}" priority for this project item.`);
        return '';
    }
    utils_debug(`triage-issues > update-board: Project item ${newProjectItemId} was moved to "${priorityText}" priority.`);
    return newProjectItemId; // New Project item ID (what we just edited). String.
}
